import assert from 'node:assert/strict';import {writeFile} from 'node:fs/promises';import {chromium} from 'playwright';import {load} from 'cheerio';import {renderedDocument} from '../../engine/form-appearance.mjs';import {extract} from '../../engine/extract.mjs';import {applyForms} from '../../scripts/form-export.mjs';import {applyComponents} from '../../scripts/component-export.mjs';
const browser=await chromium.launch({channel:'chrome'}),cases=[];let posts=0;
async function exercise(page){const f=page.locator('textarea');await f.fill('');await f.pressSequentially(Array(13).fill('word').join(' '));const typed=await f.inputValue();await f.fill('');await f.evaluate(e=>{const d=new DataTransfer();d.setData('text/plain',Array(15).fill('word').join(' '));e.dispatchEvent(new ClipboardEvent('paste',{bubbles:true,cancelable:true,clipboardData:d}));});const pasted=await f.inputValue();await f.press('Enter');const newline=await f.inputValue();return {typed,pasted,newline};}
try{for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:844}});await page.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){posts++;return r.abort();}return new URL(r.request().url()).origin==='http://127.0.0.1:9439'?r.continue():r.abort();});await page.goto('http://127.0.0.1:9439/project-note/',{waitUntil:'networkidle'});const model=extract(await renderedDocument(page),'http://127.0.0.1:9439/project-note/'),contract=model.sourceForms.find(f=>f.provider==='wpforms');assert.equal(contract.fields.find(f=>f.type==='textarea').wordLimitBehavior,'restrict');const expected=await exercise(page);await page.close();contract.delivery={endpoint:'/never'};const $=load(model.content);applyForms($,model,[contract]);applyComponents($);const exported=await browser.newPage({viewport:{width,height:844}});await exported.route('https://fixture.test/',r=>r.fulfill({contentType:'text/html',body:$.html()}));await exported.goto('https://fixture.test/');const actual=await exercise(exported);assert.deepEqual(actual,expected);assert.equal(actual.pasted.split(' ').length,12);cases.push({width,source:expected,exported:actual});await exported.close();}assert.equal(posts,0);await writeFile('artifacts/platform/wpforms-heldout/word-input-check.json',JSON.stringify({scope:'Installed source and transformed captured form behavior, not full native migration',cases,sourcePosts:posts,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length,sourcePosts:posts}));}finally{await browser.close();}
